// SP Trading API v1 — the CONTRACT, and nothing else: scopes, request and answer schemas, and the table of operations.
//
// This file is pure (zod only: no configuration, no database, no signer), so that the OpenAPI document can be generated by a
// script and by a test without starting anything. routes.ts registers exactly these operations (one handler per `id`, a missing
// or extra handler fails at start-up), and openapi.ts renders exactly this table: the document cannot drift from the server.
import { z } from 'zod';
import { CompareQuerySchema } from '../markets-hub/schema.ts'; // pure (zod only)

export const TRADING_PREFIX = '/api/v1/trading';
export const DEVELOPER_PREFIX = '/api/v1/developer';
export const API_VERSION = '1.0.0';

// ---------------------------------------------------------------------------------------------------------------- scopes
/** The closed list. There is deliberately NO scope for keys, the recovery phrase, signer administration, security settings,
 *  API-key management or mandate approval: those routes are outside TRADING_PREFIX, and a key opens nothing outside it. */
export const SCOPES = ['wallet:read', 'markets:read', 'orders:read', 'orders:prepare', 'orders:execute', 'orders:cancel', 'positions:read', 'positions:manage',
  'strategies:read', 'strategies:manage', 'agents:read', 'agents:manage'] as const;
export type Scope = (typeof SCOPES)[number];
export const ScopeSchema = z.enum(SCOPES);
/** route scope meaning "any authenticated principal" (the owner session or any valid key) — used by the OpenAPI document only */
export const ANY_SCOPE = '*' as const;
export type RouteScope = Scope | typeof ANY_SCOPE;
/** Scopes that would make a venue or the signer act. On a key they are INERT without a trading mandate bound to the key
 *  (`mandate_required`), and a scope is never what bounds execution: the signer-enforced mandate is. */
export const EXECUTION_SCOPES: readonly Scope[] = ['orders:execute', 'orders:cancel', 'positions:manage'];
/** V11 agents: `strategies:manage` and `agents:manage` are MANAGEMENT scopes — research, paper trading, pause and stop sign nothing.
 *  Going LIVE is bounded by the AGENT's own mandate (approved by the owner with the passkey, enforced by the signer): the handler
 *  answers 409 `mandate_required` without one, whatever the key holds. */
export const isExecutionScope = (s: string): boolean => (EXECUTION_SCOPES as readonly string[]).includes(s);

// ---------------------------------------------------------------------------------------------------------------- key model
export const KEY_BOUNDS = { maxDays: 365, defaultRatePerMin: 120, maxRatePerMin: 600, maxKeys: 50, maxNotionalUsd: 100_000_000 } as const;
const Usd = z.number().positive().max(KEY_BOUNDS.maxNotionalUsd);
/** recorded at creation, enforced when execution is wired; `null` = no limit of this kind on the key (the mandate still bounds it) */
export const LimitsSchema = z.strictObject({ maxOrderNotionalUsd: Usd.nullable().default(null), maxDailyNotionalUsd: Usd.nullable().default(null) });
export type Limits = z.infer<typeof LimitsSchema>;
const Name = (max: number) => z.string().regex(/^[A-Za-z0-9._:\/-]+$/).min(1).max(max);
/** an empty list means "not restricted on this axis" */
export const RestrictionsSchema = z.strictObject({
  networks: z.array(Name(24)).max(60).default([]),
  /** venue or protocol ids: hyperliquid, gmx, dydx, spot */
  venues: z.array(Name(40)).max(20).default([]),
  /** instrument ids as returned by GET /markets, e.g. hyperliquid:BTC */
  instruments: z.array(Name(120)).max(200).default([]),
  /** source addresses allowed to use the key: IPv4/IPv6 addresses or CIDR blocks */
  ipAllow: z.array(z.string().regex(/^[0-9A-Fa-f:.]{2,45}(\/\d{1,3})?$/)).max(20).default([]),
});
export type Restrictions = z.infer<typeof RestrictionsSchema>;

export const KeyCreateSchema = z.strictObject({
  name: z.string().trim().min(1).max(60),
  scopes: z.array(ScopeSchema).min(1).max(SCOPES.length),
  /** required; at most one year */
  expiresInDays: z.number().int().min(1).max(KEY_BOUNDS.maxDays),
  limits: LimitsSchema.default({ maxOrderNotionalUsd: null, maxDailyNotionalUsd: null }),
  restrictions: RestrictionsSchema.default({ networks: [], venues: [], instruments: [], ipAllow: [] }),
  rateLimitPerMin: z.number().int().min(1).max(KEY_BOUNDS.maxRatePerMin).default(KEY_BOUNDS.defaultRatePerMin),
  mandateId: z.uuid().nullable().default(null),
});
export type KeyCreate = z.infer<typeof KeyCreateSchema>;
export const KeyChangesSchema = z.strictObject({
  name: z.string().trim().min(1).max(60).optional(), scopes: z.array(ScopeSchema).min(1).max(SCOPES.length).optional(),
  /** absolute expiry, ISO 8601; at most one year after the key's creation */
  expiresAt: z.iso.datetime().optional(), limits: LimitsSchema.optional(), restrictions: RestrictionsSchema.optional(),
  rateLimitPerMin: z.number().int().min(1).max(KEY_BOUNDS.maxRatePerMin).optional(), mandateId: z.uuid().nullable().optional(),
});
export type KeyChanges = z.infer<typeof KeyChangesSchema>;

// ---------------------------------------------------------------------------------------------------------------- webhooks
/** `emitted`: an event source exists in this version. The others are defined (name and payload) and wait for their source. */
export const WEBHOOK_EVENTS = [
  { event: 'key.revoked', emitted: true, description: 'an API key was revoked (or replaced by a rotation)', payload: '{ keyId, name, reason }' },
  { event: 'risk.kill_switch', emitted: true, description: 'the emergency halt of the signer was triggered (source "signer"), or the global kill switch of the risk engine was engaged or released (source "risk_engine")',
    payload: '{ source: "signer", halted: true } | { source: "risk_engine", engaged, by, reason }' },
  { event: 'agent.updated', emitted: true, description: 'an agent was started, paused or stopped (by the owner, an API key or the risk-management agent)', payload: '{ agentId, kind, state, mode }' },
  { event: 'risk.proposal', emitted: true, description: 'the risk-management agent proposes a reduction or a pause, or acted (paused an agent, engaged the kill switch)', payload: '{ supervisorId, agentId, mode, action, code, acted, message, metrics }' },
  { event: 'order.updated', emitted: true, description: 'an order changed state: one event per transition of the unified order state machine, for every principal, mode and venue',
    payload: '{ orderId, mode, venue, instrument, status, previous, event, reason, seq, principal, mandateId }' },
] as const;
export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number]['event'];
export const WEBHOOK_EVENT_NAMES = WEBHOOK_EVENTS.map((e) => e.event) as [WebhookEvent, ...WebhookEvent[]];

// ---------------------------------------------------------------------------------------------------------------- shared shapes
const Dec = z.string().describe('decimal number as a string (never a float)');
const Ms = z.number().int().describe('milliseconds since the Unix epoch');
const Mode = z.enum(['paper', 'live']).describe('paper = simulated, live = a venue or on-chain account. The two are never merged in one figure.');
const AgentMode = z.enum(['research', 'paper', 'live']).describe('research = analysis and backtests, never an order; paper = explicit simulation; live = a real venue under an owner-approved mandate. One answer never carries two modes.');
export const ErrorSchema = z.object({ error: z.string().describe('stable machine code'), message: z.string().describe('human-readable sentence (English)') });
const PartialError = z.object({ source: z.string(), message: z.string() });
const MarketId = z.string().min(1).max(120).describe('`venue:symbol` (e.g. `hyperliquid:BTC`, `spot:ETH`); a bare symbol is accepted when it is not ambiguous');

export const MarketRow = z.looseObject({
  id: z.string(), venue: z.string(), kind: z.enum(['perpetual', 'spot']), symbol: z.string(), base: z.string(), quote: z.string(), status: z.string(),
  mark: Dec.nullable(), ts: Ms.nullable().describe('time the source produced this row (venue read time, or the last consolidated bar for spot)'),
  stale: z.boolean().describe('true when the row is older than its freshness bound or the source could not be refreshed'),
});
const Candle = z.object({ ts: Ms, open: Dec, high: Dec, low: Dec, close: Dec, volume: Dec });
const Level = z.tuple([Dec, Dec]).describe('[price, size]');

const R = {
  markets: z.object({ markets: z.array(MarketRow), total: z.number().int().describe('rows matching the filters, before `limit`'), truncated: z.boolean(), errors: z.array(PartialError), ts: Ms }),
  market: z.looseObject({ market: MarketRow, instrument: z.looseObject({}).nullable(), ticker: z.looseObject({}).nullable(), quality: z.looseObject({}).nullable(), ts: Ms, source: z.string() }),
  orderbook: z.object({ id: z.string(), bids: z.array(Level), asks: z.array(Level), ts: Ms, stale: z.boolean(), source: z.string() }),
  candles: z.object({ id: z.string(), interval: z.string(), candles: z.array(Candle), ts: Ms.nullable(), stale: z.boolean(), source: z.string() }),
  balances: z.object({ asOf: z.string(), balances: z.array(z.looseObject({ network: z.string(), asset: z.string(), symbol: z.string(), decimals: z.number().int(), amount: z.string().nullable(), display: z.string().nullable(), error: z.string().nullable() })), errors: z.array(PartialError) }),
  portfolio: z.object({
    asOf: z.string(),
    wallet: z.object({ valueUsd: z.number().nullable(), priced: z.number().int(), unpriced: z.number().int(), pricesAsOf: z.string().nullable(), balances: z.array(z.looseObject({ network: z.string(), symbol: z.string(), display: z.string().nullable(), valueUsd: z.number().nullable() })) }),
    accounts: z.array(z.looseObject({ mode: Mode, venue: z.string(), accountId: z.string(), equity: Dec.nullable(), error: z.string().nullable() })),
    totals: z.object({ walletUsd: z.number().nullable(), liveVenueEquity: Dec.nullable(), paperEquity: Dec.nullable() }).describe('three separate figures; there is no sum across modes'),
    halted: z.boolean(), errors: z.array(PartialError),
  }),
  positions: z.object({ positions: z.array(z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), accountId: z.string(), instrument: z.string().nullable(), side: z.enum(['long', 'short']), size: Dec, entryPrice: Dec, markPrice: Dec.nullable(), unrealizedPnl: Dec.nullable(), source: z.string() })), errors: z.array(PartialError), ts: Ms }),
  orders: z.object({ orders: z.array(z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), accountId: z.string().nullable(), instrument: z.string().nullable(), side: z.string().nullable(), type: z.string(), status: z.string(), final: z.boolean().nullable(), createdAt: Ms, updatedAt: Ms })), ts: Ms }),
  order: z.looseObject({ order: z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), status: z.string() }), fills: z.array(z.looseObject({})) }),
  strategies: z.object({ library: z.array(z.looseObject({ kind: z.enum(['spot', 'perp']), path: z.string(), sha256: z.string() })), versions: z.array(z.looseObject({ id: z.string(), agentId: z.string(), name: z.string(), version: z.string(), sha256: z.string(), status: z.string() })), errors: z.array(PartialError) }),
  agents: z.object({ agents: z.array(z.looseObject({ id: z.string(), kind: z.enum(['spot', 'perp', 'stream', 'supervisor']), name: z.string(), family: z.string(), state: z.string().describe('historical raw state'), mode: z.string().describe('historical raw mode'),
    lifecycle: z.enum(['active', 'paused', 'stopped']), tradingMode: z.enum(['research', 'paper', 'live']).nullable(), venue: z.string(), universe: z.array(z.string()), interval: z.string(), configVersion: z.number().int() })) }),
  agent: z.looseObject({ agent: z.looseObject({ id: z.string(), family: z.string(), state: z.enum(['active', 'paused', 'stopped']), mode: AgentMode }), mandateDraft: z.looseObject({}).nullable() }),
  agentResult: z.looseObject({ agent: z.looseObject({ id: z.string(), state: z.enum(['active', 'paused', 'stopped']), mode: AgentMode }) }),
  job: z.object({ job: z.looseObject({ id: z.string(), kind: z.string(), status: z.enum(['queued', 'running', 'done', 'failed', 'cancelled']), attempts: z.number().int() }), label: z.string().optional() }),
  signals: z.object({ mode: AgentMode, signals: z.array(z.looseObject({ id: z.string(), ts: Ms, mode: AgentMode, configVersion: z.number().int(), strategySha256: z.string(), decision: z.enum(['pending', 'acted', 'skipped']), reasonCode: z.string().nullable() })) }),
  journal: z.object({ mode: AgentMode, entries: z.array(z.looseObject({ id: z.string(), ts: Ms, mode: AgentMode, kind: z.string(), severity: z.string(), title: z.string() })) }),
  agentOrders: z.object({ mode: AgentMode, orders: z.array(z.looseObject({ id: z.string(), mode: z.enum(['paper', 'live']), instrument: z.string(), side: z.string(), state: z.string().describe('unified order state (CREATED … FILLED, CANCELLED, REJECTED, FAILED, UNKNOWN)') })) }),
  performance: z.looseObject({ mode: AgentMode, label: z.string().describe('says which mode the figures are for; a backtest is never in this answer'), points: z.number().int(), warnings: z.array(z.object({ code: z.string(), message: z.string() })) }),
  templates: z.object({ templates: z.array(z.looseObject({ id: z.string(), family: z.string(), engine: z.string(), modes: z.array(AgentMode), liveReason: z.string().nullable(), strategyInstalled: z.boolean() })) }),
  strategyResult: z.looseObject({ strategy: z.looseObject({ id: z.string(), agentId: z.string(), sha256: z.string(), status: z.string() }) }),
  risk: z.looseObject({
    killSwitch: z.object({ signerReachable: z.boolean(), signerHalted: z.boolean().nullable(), note: z.string() }),
    signerPolicy: z.looseObject({}).nullable(), capabilityLocks: z.array(z.object({ id: z.string(), on: z.boolean(), why: z.string() })),
    accounts: z.array(z.looseObject({ mode: Mode, venue: z.string(), accountId: z.string(), policy: z.looseObject({}).nullable(), halted: z.boolean().nullable() })), errors: z.array(PartialError), ts: Ms,
  }),
  activity: z.object({ items: z.array(z.looseObject({ kind: z.string(), at: z.string(), mode: Mode })) }),
  openapi: z.looseObject({ openapi: z.string() }),
  compare: z.looseObject({
    underlying: z.string(), category: z.string().nullable(), request: z.looseObject({}),
    rows: z.array(z.looseObject({ venue: z.string(), instrument: z.string(), tradable: z.boolean().describe('false: the wallet cannot trade this venue or instrument; the row is shown for information'), tradableReason: z.string().nullable(),
      cost: z.looseObject({}).nullable().describe('itemised estimate: every component is { value, reason, basis } — value null WITH the reason when an input is missing'), priceOutlier: z.boolean(), ageMs: z.number().nullable(), stale: z.boolean() })),
    discrepancies: z.array(z.looseObject({ longVenue: z.string(), shortVenue: z.string(), netEdgeEstimateBps: Dec.nullable().describe('an ESTIMATE under `assumptions`, with `risks`'), flagged: z.boolean(), actionableFromWallet: z.boolean(),
      assumptions: z.array(z.object({ code: z.string(), text: z.string() })), risks: z.array(z.object({ code: z.string(), text: z.string() })) })),
    texts: z.looseObject({ disclaimer: z.string() }), warnings: z.array(z.string()), errors: z.array(PartialError), ts: Ms, source: z.string(),
  }),
  preview: z.looseObject({ order: z.looseObject({ clientOrderId: z.string() }).describe('the canonical order SPW-ORDER-INTENT-v1'), hash: z.string().describe('SHA-256 of the canonical bytes, hex'), wouldExecute: z.boolean(),
    refusals: z.array(z.looseObject({ stage: z.enum(['key', 'lock', 'mandate', 'risk', 'engine']), code: z.string(), message: z.string() })),
    approval: z.looseObject({ required: z.boolean(), by: z.enum(['owner_passkey', 'mandate', 'none']) }),
    risk: z.looseObject({ decision: z.enum(['allow', 'deny']), reducing: z.boolean(), checks: z.array(z.looseObject({ id: z.string(), ok: z.boolean(), observed: z.string().nullable(), limit: z.string().nullable(), detail: z.string(), exempt: z.boolean() })) }),
    mandate: z.looseObject({ id: z.string(), decision: z.enum(['allow', 'deny']), reasons: z.array(z.string()) }).nullable(), engine: z.looseObject({ name: z.string() }), ts: Ms }),
  placed: z.looseObject({ order: z.looseObject({ id: z.string(), mode: Mode, venue: z.string(), status: z.string().describe('CREATED, VALIDATED, AWAITING_APPROVAL, APPROVED, SUBMITTING, SUBMITTED, PARTIALLY_FILLED, FILLED, CANCELLED, REJECTED, FAILED or UNKNOWN') }),
    idempotent: z.boolean(), approval: z.looseObject({}).nullable().describe('set while the order waits for the owner\'s passkey: where it is approved') }),
  cancelled: z.looseObject({ order: z.looseObject({ id: z.string(), status: z.string() }), sent: z.boolean(), changed: z.boolean() }),
};

// ---------------------------------------------------------------------------------------------------------------- requests
const Venue = z.string().max(40).optional().describe('venue id: hyperliquid, gmx, dydx, spot');
const Limit = (dflt: number, max: number) => z.coerce.number().int().min(1).max(max).default(dflt);
const SymbolParam = z.object({ symbol: MarketId });
const IdParam = z.object({ id: z.string().min(1).max(200) });
export const CANDLE_INTERVALS = ['1m', '5m', '15m', '1h', '4h', '1d'] as const;

export const OrderRequestSchema = z.strictObject({
  mode: Mode, accountId: z.uuid().optional().describe('paper account or venue account; required when the wallet has several on the venue'),
  instrument: MarketId, side: z.enum(['buy', 'sell']),
  type: z.enum(['limit', 'market', 'stop_market', 'stop_limit', 'take_profit_market', 'take_profit_limit']),
  size: Dec.regex(/^\d+(\.\d+)?$/), price: Dec.regex(/^\d+(\.\d+)?$/).optional(), triggerPrice: Dec.regex(/^\d+(\.\d+)?$/).optional(),
  reduceOnly: z.boolean().default(false), tif: z.enum(['gtc', 'ioc', 'alo']).default('gtc'), slippageBps: z.number().int().min(1).max(500).optional(),
  leverage: Dec.regex(/^\d+(\.\d+)?$/).optional().describe('paper only: leverage setting of the instrument on the account. On a venue account the leverage is a venue setting'),
  maxFeeUsd: Dec.regex(/^\d+(\.\d+)?$/).optional().describe('highest fee accepted, USD; default: 10 bps of the notional'),
  clientOrderId: z.string().regex(/^[A-Za-z0-9._:-]{8,100}$/).optional().describe('idempotency key of the ORDER; default: the Idempotency-Key header. The order id is derived from it and from the principal'),
});
export type OrderRequest = z.infer<typeof OrderRequestSchema>;
export const CommandBody = z.strictObject({
  text: z.string().min(1).max(300).describe('one line of the trading command grammar, English or French: LONG BTC-PERP 500 x2, CLOSE BTC-PERP 50%, CANCEL ORDER <id>, SHOW POSITIONS, KILL …'),
  mode: Mode.default('paper'), accountId: z.uuid().optional().describe('paper account or venue account; required when the wallet has several on the venue'), dryRun: z.boolean().default(false).describe('true: answer the canonical order (or the control) the command resolves to, and do nothing'),
});
const KillBody = z.strictObject({ reason: z.string().max(200).default('') });
const CloseBody = z.strictObject({ slippageBps: z.number().int().min(1).max(500).optional() });
const ReduceBody = z.strictObject({ fraction: Dec.regex(/^(0(\.\d+)?|1(\.0+)?)$/).describe('share of the position to close, in (0, 1]'), slippageBps: z.number().int().min(1).max(500).optional() });
const StrategyBody = z.strictObject({ kind: z.enum(['spot', 'perp']), path: z.string().min(1).max(200).describe('library path of the strategy'), agentId: z.uuid().optional() });
const BacktestBody = z.strictObject({ symbols: z.array(z.string().regex(/^[A-Z0-9]{2,15}$/)).min(1).max(12).optional(), interval: z.enum(['1h', '1d']).optional() });
const StartBody = z.strictObject({ mode: AgentMode, agentId: z.uuid().optional() });
const StopBody = z.strictObject({ reason: z.string().max(200).default('') });
const AgentBody = z.strictObject({ kind: z.enum(['spot', 'perp']).optional().describe('without a template: perp (a spot agent needs a vault from the signer: owner only)'), template: z.string().max(40).optional().describe('one of GET /agents/templates'),
  name: z.string().min(2).max(40), mission: z.string().max(400).default(''), universe: z.array(z.string().regex(/^[A-Z0-9]{2,15}$/)).min(1).max(12).optional(), venues: z.array(z.enum(['hyperliquid', 'edgex', 'dydx', 'gmx'])).min(1).max(2).optional(),
  strategyPath: z.string().max(60).optional(), interval: z.enum(['1h', '4h', '1d']).optional(), capitalUsdc: z.string().regex(/^\d{1,7}(\.\d{1,6})?$/).optional(), risk: z.record(z.string(), z.union([z.number(), z.string(), z.boolean()])).optional(),
  config: z.record(z.string(), z.unknown()).optional(), mode: AgentMode.default('research').describe('research (default: created, not running) or paper (stream and supervisor agents start at once); never live') });
const AgentPage = z.object({ mode: AgentMode.optional().describe('default: the mode the agent is in now'), limit: Limit(100, 500), before: z.coerce.number().int().positive().optional().describe('unix ms: rows strictly before it'), open: z.enum(['true', 'false']).optional() });
const AgentBacktestBody = z.strictObject({ versionId: z.uuid().optional(), hours: z.number().int().min(1).max(168).optional().describe('stream agents: how many hours of recorded snapshots to replay') });

// ---------------------------------------------------------------------------------------------------------------- private markets (v11)
const PmDatum = z.object({ value: Dec.nullable(), source: z.string(), ts: Ms.nullable(), stale: z.boolean() }).describe('one figure with where it comes from, when it was read, and whether it is older than its freshness bound');
const PmSize = z.string().regex(/^(0|[1-9]\d{0,11})(\.\d{1,8})?$/);
const PmRow = z.looseObject({
  id: z.string(), venue: z.string(), platform: z.string(), symbol: z.string(), company: z.object({ slug: z.string(), name: z.string() }).nullable(), status: z.enum(['live', 'delisted', 'halted', 'reduce_only']),
  review: z.looseObject({ state: z.enum(['reviewed', 'under_review', 'not_reviewed']), reasons: z.array(z.string()) }),
  contract: z.looseObject({ nature: z.string(), unit: z.object({ kind: z.enum(['usd_per_share', 'valuation_usd_billions', 'unknown']), label: z.string() }), quoteCurrency: z.string(), settlement: z.string(), oracle: z.string(), liquidation: z.string() }),
  market: z.looseObject({ price: PmDatum, funding: PmDatum.extend({ intervalSec: z.number().int().nullable() }), openInterest: PmDatum, volume24h: PmDatum }),
  valuation: z.looseObject({
    syntheticPrice: z.looseObject({ value: Dec.nullable() }), contractMarketValue: z.looseObject({ value: Dec.nullable(), reason: z.string().nullable() }), notionalExposure: z.looseObject({ value: Dec.nullable(), hypothetical: z.literal(true) }),
    impliedValuation: z.looseObject({ value: Dec.nullable(), formula: z.string().nullable(), reason: z.string().nullable(), reasonCode: z.string().nullable() }).describe('null + reason unless the reviewed definition gives the formula'),
    lastPrivateValuation: z.looseObject({ value: Dec, kind: z.string(), date: z.string(), sourceUrl: z.string() }).nullable(), premiumDiscount: z.looseObject({ premiumBps: Dec.nullable() }), caveats: z.array(z.looseObject({ code: z.string(), text: z.string() })),
  }),
  tradable: z.literal(false), notTradable: z.object({ code: z.string(), reasons: z.array(z.string()) }), error: z.string().nullable(),
});
const PM = {
  list: z.object({ delisted: z.enum(['true', 'false']).optional().describe('true: only delisted markets (frozen prices)'), size: PmSize.optional().describe('hypothetical position size, contracts (default 1)'), side: z.enum(['long', 'short']).optional() }),
  detail: z.object({ size: PmSize.optional(), side: z.enum(['long', 'short']).optional(), interval: z.enum(['1h', '1d']).optional(), limit: z.coerce.number().int().min(1).max(500).optional() }),
  id: z.string().min(3).max(120).regex(/^[a-z]+:[A-Za-z0-9:._-]+$/).describe('`venue:symbol`, e.g. `hyperliquid:io:ANTH`, `edgex:ANTHROPICUSDC`'),
  slug: z.string().regex(/^[a-z0-9-]{1,40}$/),
  listAnswer: z.looseObject({ markets: z.array(PmRow), companies: z.array(z.looseObject({ slug: z.string(), name: z.string(), contracts: z.array(z.string()) })), excluded: z.array(z.looseObject({ id: z.string(), reason: z.string() })),
    venues: z.array(z.looseObject({ venue: z.string(), status: z.enum(['ok', 'stale', 'error']), error: z.string().nullable() })), notice: z.object({ tradable: z.literal(false), code: z.string(), text: z.string() }), ts: Ms }),
  detailAnswer: z.looseObject({ market: PmRow, book: z.looseObject({}), candles: z.looseObject({}), references: z.array(z.looseObject({ kind: z.string(), date: z.string(), sourceUrl: z.string() })), ts: Ms }),
  companyAnswer: z.looseObject({ company: z.looseObject({ slug: z.string(), name: z.string() }), contracts: z.array(PmRow), delisted: z.array(PmRow), references: z.array(z.looseObject({})), merged: z.null().describe('always null: venues are never merged'), ts: Ms }),
};

// ---------------------------------------------------------------------------------------------------------------- operations
export interface OperationSpec {
  /** operationId, and the key of the handler in routes.ts */
  id: string; method: 'GET' | 'POST' | 'DELETE';
  /** Fastify path relative to TRADING_PREFIX (`:name` parameters) */
  path: string; tag: 'Markets' | 'Portfolio' | 'Orders' | 'Positions' | 'Strategies' | 'Agents' | 'Risk' | 'Meta';
  scope: RouteScope; summary: string; description?: string;
  params?: z.ZodObject; query?: z.ZodObject; body?: z.ZodType; response?: z.ZodType;
  /** mutating call: `Idempotency-Key` is required (replay protection) */
  idempotent?: boolean;
  /** false: the route exists with its scope, validation and idempotency, and answers 501 `execution_not_wired` */
  implemented: boolean;
  /** true: an execution scope that needs NO trading mandate on the key — the operation can only remove risk (a cancel, the kill switch) */
  noMandate?: boolean;
}
const NOT_WIRED = 'Not wired in this version: the call is authenticated, authorized, validated and checked for replay, then answers 501 `execution_not_wired`. It never answers 2xx.';
const START_NOTE = 'research and paper sign nothing. `live` is accepted ONLY when a mandate approved by the owner with the passkey is in force for this agent at the signer; otherwise 409 `mandate_required` (a key, an agent or this API can never approve a mandate). Families that cannot go live answer 409 `live_unavailable` with the reason.';
const STOP_NOTE = 'Always allowed. The safe wind-down: a live perp agent\'s mandate is revoked and its positions are closed with reduce-only orders; a live spot agent\'s mandate is revoked at the signer; simulated quotes are withdrawn.';
const done = (description: string): Partial<OperationSpec> => ({ implemented: true, description });
const read = (id: string, path: string, tag: OperationSpec['tag'], scope: RouteScope, summary: string, o: Partial<OperationSpec> = {}): OperationSpec => ({ id, method: 'GET', path, tag, scope, summary, implemented: true, ...o });
const write = (id: string, method: 'POST' | 'DELETE', path: string, tag: OperationSpec['tag'], scope: Scope, summary: string, o: Partial<OperationSpec> = {}): OperationSpec =>
  ({ id, method, path, tag, scope, summary, description: NOT_WIRED, idempotent: true, implemented: false, ...o });

